# Let me manually analyze the transformations
inputs = ['iwiu', 'hfcgd', 'hhzkvj', 'uuav', 'dyvbi']
outputs = ['iwidbd', 'hfcbd', 'hhzkvj', 'dbddbdvfdbdv', 'dyvbi']

print("Analyzing transformations:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"{inp} → {outp}")

# Let me try to find patterns by checking what characters differ
print("\nDetailed character analysis:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"\n{i+1}. {inp} → {outp}")
    if inp != outp:
        for j, (char_in, char_out) in enumerate(zip(inp, outp)):
            if char_in != char_out:
                print(f"  Position {j}: '{char_in}' → '{char_out}'")
        # Check extra characters in output
        if len(outp) > len(inp):
            print(f"  Extra chars in output: {outp[len(inp):]}")

